import React,{useEffect,useMemo,useState}from'react';
import{useAuth}from'../auth/AuthContext.jsx';
import{VbenAlert,VbenBadge,VbenButton,VbenCard,VbenDateTime,VbenField,VbenIcon,VbenInput,VbenMetric,VbenModal,VbenMoney,VbenPermissionNote,VbenSelect,VbenSkeleton,VbenTable,VbenTabs,VbenTextarea,VbenToast,vbenStatusTone}from'../components/VbenUI.jsx';

const METHOD_FRESH={code:'',name:'',fulfillment_mode:'SHIPPING',status:'ACTIVE',flat_fee:0,free_over:'',min_order:0,estimated_min_minutes:60,estimated_max_minutes:180,sort_order:0,public_config:'{}'};
const PRICING_FRESH={pricing_mode:'BASELINE',zone_no_match_policy:'UNAVAILABLE'};
const DIGITAL_FRESH={product_id:'',product_type:'DIGITAL_VIDEO',access_mode:'VIEW_ONLY',download_limit:''};
const ZONE_FRESH={code:'',name:'',status:'ACTIVE',match_type:'COUNTRY_REGION',country_codes:'',region_names:'',center_latitude:'',center_longitude:'',radius_km:'',sort_order:0};
const RATE_FRESH={zone_id:'',delivery_method_id:'',status:'ACTIVE',flat_fee:0,free_over:'',min_order:0,estimated_min_minutes:'',estimated_max_minutes:'',priority:0};
const DRIVER_FRESH={display_name:'',phone_e164:'',status:'ACTIVE',vehicle_type:'MOTORBIKE',vehicle_label:'',merchant_user_id:''};
const DISPATCH_STATUSES=['ASSIGNED','ACCEPTED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLED'];
const DISPATCHABLE_TYPES=new Set(['PHYSICAL_SHIPPING','PHYSICAL_LOCAL_DELIVERY','FOOD_DELIVERY']);
const TERMINAL_FULFILLMENT=new Set(['DELIVERED','COMPLETED','FAILED','CANCELLED']);
const DIGITAL_ACCESS=[
 {value:'VIEW_ONLY',label:'View in secure library only'},
 {value:'DOWNLOAD_ONLY',label:'Download only'},
 {value:'VIEW_AND_DOWNLOAD',label:'View in library + allow download'},
];
const humanize=value=>String(value||'').replaceAll('_',' ');
const csv=value=>[...new Set(String(value||'').split(',').map(x=>x.trim()).filter(Boolean))];
const nullableNumber=value=>value===''||value===null||value===undefined?null:Number(value);
const pricingErrorText=error=>error?.code==='DELIVERY_ZONE_RATE_REQUIRED'?'Backend requires at least one ACTIVE rate in an ACTIVE zone for this delivery method before Zone-aware pricing can be enabled.':error?.code==='DELIVERY_ZONE_PRICING_MODE_INVALID'?'Zone-aware pricing is available only for Shipping and Local delivery methods.':error?.message||'The checkout pricing policy could not be updated.';

export function DeliveryPage(){
 const{api,has}=useAuth();
 const[tab,setTab]=useState('methods');
 const[methods,setMethods]=useState([]),[products,setProducts]=useState([]),[zones,setZones]=useState([]),[rates,setRates]=useState([]),[drivers,setDrivers]=useState([]),[dispatches,setDispatches]=useState([]);
 const[err,setErr]=useState(null),[toast,setToast]=useState(''),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');
 const[methodOpen,setMethodOpen]=useState(false),[methodEdit,setMethodEdit]=useState(null),[methodForm,setMethodForm]=useState(METHOD_FRESH);
 const[pricingDraft,setPricingDraft]=useState(PRICING_FRESH),[pricingError,setPricingError]=useState(null);
 const[digitalOpen,setDigitalOpen]=useState(false),[digitalForm,setDigitalForm]=useState(DIGITAL_FRESH);
 const[zoneOpen,setZoneOpen]=useState(false),[zoneEdit,setZoneEdit]=useState(null),[zoneForm,setZoneForm]=useState(ZONE_FRESH);
 const[rateOpen,setRateOpen]=useState(false),[rateEdit,setRateEdit]=useState(null),[rateForm,setRateForm]=useState(RATE_FRESH);
 const[driverOpen,setDriverOpen]=useState(false),[driverEdit,setDriverEdit]=useState(null),[driverForm,setDriverForm]=useState(DRIVER_FRESH);
 const[dispatchOpen,setDispatchOpen]=useState(false),[dispatchDetail,setDispatchDetail]=useState(null),[dispatchDriver,setDispatchDriver]=useState(''),[dispatchNote,setDispatchNote]=useState(''),[dispatchCancelReason,setDispatchCancelReason]=useState('');
 const[orderRef,setOrderRef]=useState(''),[dispatchOrder,setDispatchOrder]=useState(null),[dispatchFulfillment,setDispatchFulfillment]=useState(''),[dispatchNewDriver,setDispatchNewDriver]=useState(''),[dispatchNewNote,setDispatchNewNote]=useState('');
 const[q,setQ]=useState(''),[mode,setMode]=useState(''),[statusFilter,setStatusFilter]=useState(''),[dispatchStatus,setDispatchStatus]=useState(''),[dispatchDriverFilter,setDispatchDriverFilter]=useState('');

 const load=async()=>{
  setErr(null);setLoading(true);
  try{
   const[m,z,d,x]=await Promise.all([
    api.request('/v1/merchant/delivery-methods'),
    api.request('/v1/merchant/delivery/zones'),
    api.request('/v1/merchant/delivery/drivers'),
    api.request('/v1/merchant/delivery/dispatches',{query:{limit:200}}),
   ]);
   setMethods(m.data.delivery_methods||[]);setZones(z.data.zones||[]);setRates(z.data.rates||[]);setDrivers(d.data.drivers||[]);setDispatches(x.data.dispatches||[]);
  }catch(e){setErr(e)}finally{setLoading(false)}
 };
 const loadProducts=async()=>{if(!has('catalog.read'))return;try{const d=await api.request('/v1/merchant/products',{query:{limit:100}});setProducts(d.data.products||[])}catch(e){setErr(e)}};
 useEffect(()=>{load();loadProducts()},[]);

 const parseConfig=x=>{try{const v=JSON.parse(x||'{}');if(!v||Array.isArray(v)||typeof v!=='object')throw new Error();return v}catch{const e=new Error('Public configuration must be a valid JSON object');e.code='INVALID_JSON';throw e}};
 const methodPayload=f=>({...f,public_config:typeof f.public_config==='string'?parseConfig(f.public_config):(f.public_config||{}),flat_fee:Number(f.flat_fee||0),min_order:Number(f.min_order||0),free_over:nullableNumber(f.free_over),estimated_min_minutes:nullableNumber(f.estimated_min_minutes),estimated_max_minutes:nullableNumber(f.estimated_max_minutes),sort_order:Number(f.sort_order||0)});
 const createMethod=async e=>{e.preventDefault();setBusy('method-create');try{await api.request('/v1/merchant/delivery-methods',{method:'POST',body:methodPayload(methodForm)});setMethodOpen(false);setMethodForm(METHOD_FRESH);setToast('Delivery method created with Baseline checkout pricing');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const startMethodEdit=r=>{setMethodEdit({...r,free_over:r.free_over??'',public_config:JSON.stringify(r.public_config||{},null,2)});setPricingDraft({pricing_mode:r.pricing_mode||'BASELINE',zone_no_match_policy:r.zone_no_match_policy||'UNAVAILABLE'});setPricingError(null)};
 const closeMethodEdit=()=>{if(busy)return;setMethodEdit(null);setPricingDraft(PRICING_FRESH);setPricingError(null)};
 const saveMethod=async()=>{setBusy('method-save');try{await api.request(`/v1/merchant/delivery-methods/${encodeURIComponent(methodEdit.id)}`,{method:'PATCH',body:methodPayload({name:methodEdit.name,status:methodEdit.status,flat_fee:methodEdit.flat_fee,free_over:methodEdit.free_over,min_order:methodEdit.min_order,estimated_min_minutes:methodEdit.estimated_min_minutes,estimated_max_minutes:methodEdit.estimated_max_minutes,sort_order:methodEdit.sort_order,public_config:methodEdit.public_config})});setMethodEdit(null);setPricingError(null);setToast('Delivery method updated');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const savePricingPolicy=async()=>{if(!methodEdit)return;setBusy('pricing-policy');setPricingError(null);try{const result=await api.request(`/v1/merchant/delivery-methods/${encodeURIComponent(methodEdit.id)}/pricing-policy`,{method:'PUT',body:{pricing_mode:pricingDraft.pricing_mode,zone_no_match_policy:pricingDraft.zone_no_match_policy}});const saved=result.data.delivery_method||{};setMethodEdit(current=>current?{...current,pricing_mode:saved.pricing_mode||pricingDraft.pricing_mode,zone_no_match_policy:saved.zone_no_match_policy||pricingDraft.zone_no_match_policy}:current);setPricingDraft({pricing_mode:saved.pricing_mode||pricingDraft.pricing_mode,zone_no_match_policy:saved.zone_no_match_policy||pricingDraft.zone_no_match_policy});setToast(saved.pricing_mode==='ZONE_AWARE'?'Zone-aware checkout pricing enabled':'Baseline checkout pricing enabled');await load()}catch(e){setPricingError(e)}finally{setBusy('')}};
 const openDigitalConversion=()=>{const first=products[0];setDigitalForm({...DIGITAL_FRESH,product_id:first?.public_id||'',product_type:first?.product_type==='DIGITAL_IMAGE'?'DIGITAL_IMAGE':'DIGITAL_VIDEO'});setDigitalOpen(true)};
 const convertDigital=async e=>{e.preventDefault();if(!digitalForm.product_id)return;setBusy('digital');setErr(null);try{const body={product_type:digitalForm.product_type,access_mode:digitalForm.access_mode,download_limit:digitalForm.access_mode==='VIEW_ONLY'?null:nullableNumber(digitalForm.download_limit)};const result=await api.request(`/v1/merchant/products/${encodeURIComponent(digitalForm.product_id)}/nature`,{method:'PUT',body});const repaired=Number(result.data.conversion?.repaired_active_cart_items||0);setDigitalOpen(false);setToast(`Product converted to ${humanize(digitalForm.product_type)}${repaired?` · ${repaired} active cart item${repaired===1?'':'s'} repaired`:''}`);await loadProducts()}catch(e){setErr(e)}finally{setBusy('')}};

 const zonePayload=(f,{includeCode=true}={})=>({...(includeCode?{code:f.code.trim()}:{}),name:f.name.trim(),status:f.status,match_type:f.match_type,country_codes:f.match_type==='COUNTRY_REGION'?csv(f.country_codes).map(x=>x.toUpperCase()):[],region_names:f.match_type==='COUNTRY_REGION'?csv(f.region_names):[],center_latitude:f.match_type==='RADIUS'?nullableNumber(f.center_latitude):null,center_longitude:f.match_type==='RADIUS'?nullableNumber(f.center_longitude):null,radius_km:f.match_type==='RADIUS'?nullableNumber(f.radius_km):null,sort_order:Number(f.sort_order||0)});
 const createZone=async e=>{e.preventDefault();setBusy('zone-create');try{await api.request('/v1/merchant/delivery/zones',{method:'POST',body:zonePayload(zoneForm)});setZoneOpen(false);setZoneForm(ZONE_FRESH);setToast('Delivery zone created');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const startZoneEdit=z=>setZoneEdit({...z,country_codes:(z.country_codes||[]).join(', '),region_names:(z.region_names||[]).join(', '),center_latitude:z.center_latitude??'',center_longitude:z.center_longitude??'',radius_km:z.radius_km??''});
 const saveZone=async()=>{setBusy('zone-save');try{await api.request(`/v1/merchant/delivery/zones/${encodeURIComponent(zoneEdit.id)}`,{method:'PATCH',body:zonePayload(zoneEdit,{includeCode:false})});setZoneEdit(null);setToast('Delivery zone updated');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const openRate=(zoneId='')=>{const eligible=methods.find(m=>['SHIPPING','LOCAL_DELIVERY'].includes(m.fulfillment_mode));setRateForm({...RATE_FRESH,zone_id:zoneId||zones[0]?.id||'',delivery_method_id:eligible?.id||''});setRateOpen(true)};
 const ratePayload=f=>({status:f.status,flat_fee:Number(f.flat_fee||0),free_over:nullableNumber(f.free_over),min_order:Number(f.min_order||0),estimated_min_minutes:nullableNumber(f.estimated_min_minutes),estimated_max_minutes:nullableNumber(f.estimated_max_minutes),priority:Number(f.priority||0)});
 const createRate=async e=>{e.preventDefault();setBusy('rate-create');try{await api.request(`/v1/merchant/delivery/zones/${encodeURIComponent(rateForm.zone_id)}/rates`,{method:'POST',body:{delivery_method_id:rateForm.delivery_method_id,...ratePayload(rateForm)}});setRateOpen(false);setRateForm(RATE_FRESH);setToast('Zone rate saved · checkout pricing policy unchanged');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const startRateEdit=r=>setRateEdit({...r,free_over:r.free_over??'',estimated_min_minutes:r.estimated_min_minutes??'',estimated_max_minutes:r.estimated_max_minutes??''});
 const saveRate=async()=>{setBusy('rate-save');try{await api.request(`/v1/merchant/delivery/zone-rates/${encodeURIComponent(rateEdit.id)}`,{method:'PATCH',body:ratePayload(rateEdit)});setRateEdit(null);setToast('Zone rate updated · checkout pricing policy unchanged');await load()}catch(e){setErr(e)}finally{setBusy('')}};

 const driverPayload=f=>({display_name:f.display_name.trim(),phone_e164:f.phone_e164.trim()||null,status:f.status,vehicle_type:f.vehicle_type||null,vehicle_label:f.vehicle_label.trim()||null,merchant_user_id:f.merchant_user_id.trim()||null});
 const createDriver=async e=>{e.preventDefault();setBusy('driver-create');try{await api.request('/v1/merchant/delivery/drivers',{method:'POST',body:driverPayload(driverForm)});setDriverOpen(false);setDriverForm(DRIVER_FRESH);setToast('Driver created');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const startDriverEdit=d=>setDriverEdit({...d,phone_e164:d.phone_e164||'',vehicle_type:d.vehicle_type||'',vehicle_label:d.vehicle_label||'',merchant_user_id:d.merchant_user_id||''});
 const saveDriver=async()=>{setBusy('driver-save');try{await api.request(`/v1/merchant/delivery/drivers/${encodeURIComponent(driverEdit.id)}`,{method:'PATCH',body:driverPayload(driverEdit)});setDriverEdit(null);setToast('Driver updated');await load()}catch(e){setErr(e)}finally{setBusy('')}};

 const loadDispatchOrder=async()=>{if(!orderRef.trim())return;setBusy('order-lookup');setDispatchOrder(null);setDispatchFulfillment('');try{const d=await api.request(`/v1/merchant/orders/${encodeURIComponent(orderRef.trim())}`);const order=d.data.order;setDispatchOrder(order);const eligible=(order.fulfillments||[]).find(f=>DISPATCHABLE_TYPES.has(f.fulfillment_type)&&!TERMINAL_FULFILLMENT.has(f.status));setDispatchFulfillment(eligible?.id||'')}catch(e){setErr(e)}finally{setBusy('')}};
 const createDispatch=async e=>{e.preventDefault();if(!dispatchFulfillment||!dispatchNewDriver)return;setBusy('dispatch-create');try{await api.request('/v1/merchant/delivery/dispatches',{method:'POST',body:{fulfillment_id:dispatchFulfillment,driver_id:dispatchNewDriver,notes:dispatchNewNote.trim()||null}});setDispatchOpen(false);setOrderRef('');setDispatchOrder(null);setDispatchFulfillment('');setDispatchNewDriver('');setDispatchNewNote('');setToast('Dispatch assignment created');await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const openDispatch=async d=>{setBusy(`dispatch:${d.id}`);try{const r=await api.request(`/v1/merchant/delivery/dispatches/${encodeURIComponent(d.id)}`);setDispatchDetail(r.data.dispatch);setDispatchDriver(r.data.dispatch.driver_id||'');setDispatchNote(r.data.dispatch.notes||'');setDispatchCancelReason('')}catch(e){setErr(e)}finally{setBusy('')}};
 const saveDispatch=async()=>{if(!dispatchDetail)return;setBusy('dispatch-save');try{const body={driver_id:dispatchDriver,notes:dispatchNote.trim()||null};await api.request(`/v1/merchant/delivery/dispatches/${encodeURIComponent(dispatchDetail.id)}`,{method:'PATCH',body});setToast('Dispatch assignment updated');setDispatchDetail(null);await load()}catch(e){setErr(e)}finally{setBusy('')}};
 const cancelDispatch=async()=>{if(!dispatchDetail)return;setBusy('dispatch-cancel');try{await api.request(`/v1/merchant/delivery/dispatches/${encodeURIComponent(dispatchDetail.id)}`,{method:'PATCH',body:{cancel:true,reason:dispatchCancelReason.trim()||'Cancelled by merchant',notes:dispatchNote.trim()||null}});setToast('Dispatch assignment cancelled');setDispatchDetail(null);await load()}catch(e){setErr(e)}finally{setBusy('')}};

 const filteredMethods=useMemo(()=>{const x=q.trim().toLowerCase();return methods.filter(r=>(!mode||r.fulfillment_mode===mode)&&(!statusFilter||r.status===statusFilter)&&(!x||`${r.name||''} ${r.code||''} ${r.fulfillment_mode||''}`.toLowerCase().includes(x)))},[methods,q,mode,statusFilter]);
 const filteredDispatches=useMemo(()=>dispatches.filter(d=>(!dispatchStatus||d.status===dispatchStatus)&&(!dispatchDriverFilter||d.driver_id===dispatchDriverFilter)),[dispatches,dispatchStatus,dispatchDriverFilter]);
 const activeDrivers=useMemo(()=>drivers.filter(d=>d.status==='ACTIVE'),[drivers]);
 const dispatchableMethods=useMemo(()=>methods.filter(m=>['SHIPPING','LOCAL_DELIVERY'].includes(m.fulfillment_mode)),[methods]);
 const activeZoneIds=useMemo(()=>new Set(zones.filter(z=>z.status==='ACTIVE').map(z=>z.id)),[zones]);
 const activeRateCounts=useMemo(()=>{const out={};for(const r of rates){if(r.status==='ACTIVE'&&activeZoneIds.has(r.zone_id))out[r.delivery_method_id]=(out[r.delivery_method_id]||0)+1}return out},[rates,activeZoneIds]);
 const selectedDigitalProduct=products.find(x=>x.public_id===digitalForm.product_id)||null;
 const methodMetrics=useMemo(()=>({all:methods.length,active:methods.filter(x=>x.status==='ACTIVE').length,shipping:methods.filter(x=>x.fulfillment_mode==='SHIPPING').length,local:methods.filter(x=>x.fulfillment_mode!=='SHIPPING').length,zoneAware:methods.filter(x=>x.pricing_mode==='ZONE_AWARE').length}),[methods]);
 const operationsMetrics=useMemo(()=>({zones:zones.filter(z=>z.status==='ACTIVE').length,rates:rates.filter(r=>r.status==='ACTIVE').length,drivers:activeDrivers.length,dispatches:dispatches.filter(d=>!['DELIVERED','CANCELLED'].includes(d.status)).length}),[zones,rates,activeDrivers,dispatches]);
 const dispatchableFulfillments=useMemo(()=>(dispatchOrder?.fulfillments||[]).filter(f=>DISPATCHABLE_TYPES.has(f.fulfillment_type)&&!TERMINAL_FULFILLMENT.has(f.status)),[dispatchOrder]);

 const openPrimary=()=>{if(tab==='methods')setMethodOpen(true);else if(tab==='zones')setZoneOpen(true);else if(tab==='drivers')setDriverOpen(true);else{setDispatchNewDriver(activeDrivers[0]?.id||'');setDispatchOpen(true)}};
 const primaryLabel=tab==='methods'?'Add delivery method':tab==='zones'?'Add delivery zone':tab==='drivers'?'Add driver':'Assign dispatch';
 if(!has('delivery.read'))return <VbenPermissionNote permission="delivery.read"/>;

 return <div className="vben-delivery-page delivery-ops-v1" data-testid="delivery-operations-v1">
  <header className="vben-delivery-head"><div><span className="vben-delivery-kicker"><VbenIcon name="truck" size={14}/> Commerce operations</span><h1>Delivery operations</h1><p>Manage checkout delivery methods, explicit zone-aware pricing, store-scoped drivers and audited fulfillment dispatch assignments from one workspace.</p></div><div className="vben-delivery-head-actions"><VbenButton variant="secondary" icon="refresh" onClick={()=>{load();loadProducts()}} loading={loading}>Refresh</VbenButton>{has('delivery.manage')&&<VbenButton icon="plus" onClick={openPrimary}>{primaryLabel}</VbenButton>}</div></header>
  {err&&<VbenAlert tone="danger" title={err.code||'Delivery operation failed'}>{err.message||'The delivery operation could not be completed.'}</VbenAlert>}
  <section className="vben-delivery-metrics">{tab==='methods'?<><VbenMetric label="Methods" value={methodMetrics.all} detail="Configured methods" icon="truck"/><VbenMetric label="Active" value={methodMetrics.active} detail="Customer available" icon="check" tone="success"/><VbenMetric label="Shipping" value={methodMetrics.shipping} detail="Shipping methods" icon="box"/><VbenMetric label="Pickup / local" value={methodMetrics.local} detail={`${methodMetrics.zoneAware} zone-aware`} icon="mapPin" tone="neutral"/></>:<><VbenMetric label="Active zones" value={operationsMetrics.zones} detail="Stored matching rules" icon="mapPin"/><VbenMetric label="Active rates" value={operationsMetrics.rates} detail="Zone pricing inputs" icon="payments"/><VbenMetric label="Active drivers" value={operationsMetrics.drivers} detail="Available for dispatch" icon="users" tone="success"/><VbenMetric label="Open dispatches" value={operationsMetrics.dispatches} detail="Operational assignments" icon="truck"/></>}</section>
  <VbenCard className="vben-delivery-card delivery-ops-card"><VbenTabs value={tab} onChange={setTab} items={[{value:'methods',label:'Methods',count:methods.length},{value:'zones',label:'Zones & Rates',count:zones.length},{value:'drivers',label:'Drivers',count:drivers.length},{value:'dispatch',label:'Dispatch',count:operationsMetrics.dispatches}]}/>
   {tab==='methods'&&<MethodsTab loading={loading} methods={filteredMethods} q={q} setQ={setQ} mode={mode} setMode={setMode} statusFilter={statusFilter} setStatusFilter={setStatusFilter} has={has} onEdit={startMethodEdit} products={products} openDigitalConversion={openDigitalConversion}/>} 
   {tab==='zones'&&<ZonesTab loading={loading} zones={zones} rates={rates} methods={dispatchableMethods} zoneAwareCount={methodMetrics.zoneAware} has={has} onEditZone={startZoneEdit} onNewRate={openRate} onEditRate={startRateEdit}/>} 
   {tab==='drivers'&&<DriversTab loading={loading} drivers={drivers} has={has} onEdit={startDriverEdit}/>} 
   {tab==='dispatch'&&<DispatchTab loading={loading} dispatches={filteredDispatches} drivers={drivers} status={dispatchStatus} setStatus={setDispatchStatus} driverFilter={dispatchDriverFilter} setDriverFilter={setDispatchDriverFilter} busy={busy} onOpen={openDispatch}/>} 
  </VbenCard>

  <VbenModal open={methodOpen} onClose={()=>!busy&&setMethodOpen(false)} title="New delivery method" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setMethodOpen(false)}>Cancel</VbenButton><VbenButton type="submit" form="delivery-method-form" loading={busy==='method-create'}>Create method</VbenButton></>}><MethodForm form={methodForm} setForm={setMethodForm} onSubmit={createMethod} id="delivery-method-form" includeCode/><VbenAlert tone="info" title="Checkout pricing starts safely">New delivery methods use Baseline pricing. Create active zone rates first, then explicitly opt the method into Zone-aware pricing from Edit method.</VbenAlert></VbenModal>
  <VbenModal open={!!methodEdit} onClose={closeMethodEdit} title="Edit delivery method" size="xl" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={closeMethodEdit}>Close</VbenButton><VbenButton onClick={saveMethod} loading={busy==='method-save'} disabled={busy==='pricing-policy'}>Save method settings</VbenButton></>}>{methodEdit&&<div className="vben-delivery-edit"><div className="vben-delivery-summary"><div><span>Code</span><strong>{methodEdit.code}</strong></div><div><span>Mode</span><strong>{methodEdit.fulfillment_mode}</strong></div></div><MethodFields form={methodEdit} setForm={setMethodEdit}/><PricingPolicyEditor method={methodEdit} form={pricingDraft} setForm={setPricingDraft} onSave={savePricingPolicy} busy={busy==='pricing-policy'} error={pricingError} activeRateCount={activeRateCounts[methodEdit.id]||0}/></div>}</VbenModal>

  <VbenModal open={digitalOpen} onClose={()=>!busy&&setDigitalOpen(false)} title="Convert existing product to digital" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setDigitalOpen(false)}>Cancel</VbenButton><VbenButton type="submit" form="digital-product-conversion" loading={busy==='digital'} disabled={!digitalForm.product_id}>Convert product</VbenButton></>}><form id="digital-product-conversion" onSubmit={convertDigital} className="vben-delivery-form"><VbenAlert tone="warning" title="Safe conversion rule">Product Nature can change only when the product has no order history. Existing orders are never rewritten. Any incompatible item in an active customer cart is repaired automatically.</VbenAlert><div className="vben-delivery-form-grid"><VbenField label="Product" className="vben-delivery-span-2"><VbenSelect value={digitalForm.product_id} onChange={e=>setDigitalForm({...digitalForm,product_id:e.target.value})}>{products.map(p=><option key={p.public_id} value={p.public_id}>{p.name} · {p.product_type}</option>)}</VbenSelect>{selectedDigitalProduct&&<small>Current nature: {selectedDigitalProduct.product_type}</small>}</VbenField><VbenField label="New Product Nature"><VbenSelect value={digitalForm.product_type} onChange={e=>setDigitalForm({...digitalForm,product_type:e.target.value})}><option value="DIGITAL_VIDEO">Digital video</option><option value="DIGITAL_IMAGE">Digital image</option></VbenSelect></VbenField><VbenField label="Customer access"><VbenSelect value={digitalForm.access_mode} onChange={e=>setDigitalForm({...digitalForm,access_mode:e.target.value,download_limit:e.target.value==='VIEW_ONLY'?'':digitalForm.download_limit})}>{DIGITAL_ACCESS.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</VbenSelect></VbenField>{digitalForm.access_mode!=='VIEW_ONLY'&&<VbenField label="Download limit" hint="Leave blank for unlimited downloads."><VbenInput type="number" min="0" step="1" value={digitalForm.download_limit} onChange={e=>setDigitalForm({...digitalForm,download_limit:e.target.value})} placeholder="Unlimited"/></VbenField>}<div className="vben-delivery-span-2"><VbenAlert tone="info" title="After conversion">Attach purchased image/video media as PRIVATE. Customers receive it through My Library only after trusted PAID status.</VbenAlert></div></div></form></VbenModal>

  <VbenModal open={zoneOpen} onClose={()=>!busy&&setZoneOpen(false)} title="New delivery zone" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setZoneOpen(false)}>Cancel</VbenButton><VbenButton type="submit" form="delivery-zone-form" loading={busy==='zone-create'}>Create zone</VbenButton></>}><ZoneForm form={zoneForm} setForm={setZoneForm} onSubmit={createZone} id="delivery-zone-form" includeCode/></VbenModal>
  <VbenModal open={!!zoneEdit} onClose={()=>!busy&&setZoneEdit(null)} title="Edit delivery zone" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setZoneEdit(null)}>Cancel</VbenButton><VbenButton onClick={saveZone} loading={busy==='zone-save'}>Save zone</VbenButton></>}>{zoneEdit&&<ZoneFields form={zoneEdit} setForm={setZoneEdit}/>}</VbenModal>

  <VbenModal open={rateOpen} onClose={()=>!busy&&setRateOpen(false)} title="New zone rate" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setRateOpen(false)}>Cancel</VbenButton><VbenButton type="submit" form="zone-rate-form" loading={busy==='rate-create'} disabled={!rateForm.zone_id||!rateForm.delivery_method_id}>Save rate</VbenButton></>}><RateForm form={rateForm} setForm={setRateForm} zones={zones} methods={dispatchableMethods} onSubmit={createRate} id="zone-rate-form"/></VbenModal>
  <VbenModal open={!!rateEdit} onClose={()=>!busy&&setRateEdit(null)} title="Edit zone rate" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setRateEdit(null)}>Cancel</VbenButton><VbenButton onClick={saveRate} loading={busy==='rate-save'}>Save rate</VbenButton></>}>{rateEdit&&<div className="delivery-ops-form-stack"><VbenAlert tone="info" title="Pricing policy stays explicit">Editing a rate never changes a Delivery Method between Baseline and Zone-aware pricing. Activation is controlled separately on the method.</VbenAlert><div className="vben-delivery-summary"><div><span>Zone</span><strong>{rateEdit.zone_code}</strong></div><div><span>Method</span><strong>{rateEdit.delivery_method_name}</strong></div></div><RateFields form={rateEdit} setForm={setRateEdit}/></div>}</VbenModal>

  <VbenModal open={driverOpen} onClose={()=>!busy&&setDriverOpen(false)} title="New delivery driver" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setDriverOpen(false)}>Cancel</VbenButton><VbenButton type="submit" form="delivery-driver-form" loading={busy==='driver-create'}>Create driver</VbenButton></>}><DriverForm form={driverForm} setForm={setDriverForm} onSubmit={createDriver} id="delivery-driver-form"/></VbenModal>
  <VbenModal open={!!driverEdit} onClose={()=>!busy&&setDriverEdit(null)} title="Edit delivery driver" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setDriverEdit(null)}>Cancel</VbenButton><VbenButton onClick={saveDriver} loading={busy==='driver-save'}>Save driver</VbenButton></>}>{driverEdit&&<DriverFields form={driverEdit} setForm={setDriverEdit}/>}</VbenModal>

  <VbenModal open={dispatchOpen} onClose={()=>!busy&&setDispatchOpen(false)} title="Assign fulfillment to driver" size="lg" footer={<><VbenButton variant="secondary" disabled={!!busy} onClick={()=>setDispatchOpen(false)}>Cancel</VbenButton><VbenButton type="submit" form="dispatch-assignment-form" loading={busy==='dispatch-create'} disabled={!dispatchFulfillment||!dispatchNewDriver}>Assign driver</VbenButton></>}><form id="dispatch-assignment-form" onSubmit={createDispatch} className="delivery-ops-form-stack"><VbenAlert tone="info" title="Dispatch is operational only">Assignment does not change the fulfillment status. Order and fulfillment transitions remain controlled from the Orders workspace.</VbenAlert><div className="delivery-order-lookup"><VbenField label="Order number / reference"><VbenInput value={orderRef} onChange={e=>setOrderRef(e.target.value)} placeholder="ORD-…"/></VbenField><VbenButton variant="secondary" icon="search" onClick={loadDispatchOrder} loading={busy==='order-lookup'} disabled={!orderRef.trim()}>Load order</VbenButton></div>{dispatchOrder&&<><div className="delivery-order-summary"><div><span>Order</span><strong>{dispatchOrder.order_number}</strong></div><div><span>Status</span><VbenBadge tone={vbenStatusTone(dispatchOrder.status)}>{humanize(dispatchOrder.status)}</VbenBadge></div></div><div className="vben-delivery-form-grid"><VbenField label="Dispatchable fulfillment"><VbenSelect value={dispatchFulfillment} onChange={e=>setDispatchFulfillment(e.target.value)}><option value="">Choose fulfillment</option>{dispatchableFulfillments.map(f=><option key={f.id} value={f.id}>{humanize(f.fulfillment_type)} · {humanize(f.status)}</option>)}</VbenSelect>{!dispatchableFulfillments.length&&<small>No non-terminal shipping/delivery fulfillment is available on this order.</small>}</VbenField><VbenField label="Driver"><VbenSelect value={dispatchNewDriver} onChange={e=>setDispatchNewDriver(e.target.value)}><option value="">Choose active driver</option>{activeDrivers.map(d=><option key={d.id} value={d.id}>{d.display_name}{d.vehicle_label?` · ${d.vehicle_label}`:''}</option>)}</VbenSelect></VbenField><VbenField label="Assignment note" className="vben-delivery-span-2"><VbenTextarea value={dispatchNewNote} onChange={e=>setDispatchNewNote(e.target.value)} placeholder="Optional dispatch instructions" maxLength={2000}/></VbenField></div></>}</form></VbenModal>

  <VbenModal open={!!dispatchDetail} onClose={()=>!busy&&setDispatchDetail(null)} title={dispatchDetail?`Dispatch · ${dispatchDetail.order_number}`:'Dispatch'} size="xl" footer={dispatchDetail&&!['DELIVERED','CANCELLED'].includes(dispatchDetail.status)&&has('delivery.manage')?<><VbenButton variant="danger" disabled={!!busy} onClick={cancelDispatch} loading={busy==='dispatch-cancel'}>Cancel dispatch</VbenButton><VbenButton onClick={saveDispatch} loading={busy==='dispatch-save'}>Save assignment</VbenButton></>:null}>{dispatchDetail&&<div className="delivery-dispatch-detail"><div className="delivery-order-summary"><div><span>Status</span><VbenBadge tone={vbenStatusTone(dispatchDetail.status)}>{humanize(dispatchDetail.status)}</VbenBadge></div><div><span>Fulfillment</span><strong>{humanize(dispatchDetail.fulfillment_type)}</strong></div><div><span>Fulfillment status</span><VbenBadge tone={vbenStatusTone(dispatchDetail.fulfillment_status)}>{humanize(dispatchDetail.fulfillment_status)}</VbenBadge></div></div>{!['DELIVERED','CANCELLED'].includes(dispatchDetail.status)&&has('delivery.manage')&&<div className="vben-delivery-form-grid"><VbenField label="Assigned driver"><VbenSelect value={dispatchDriver} onChange={e=>setDispatchDriver(e.target.value)}>{activeDrivers.map(d=><option key={d.id} value={d.id}>{d.display_name}{d.vehicle_label?` · ${d.vehicle_label}`:''}</option>)}</VbenSelect></VbenField><VbenField label="Cancel reason"><VbenInput value={dispatchCancelReason} onChange={e=>setDispatchCancelReason(e.target.value)} placeholder="Used only if cancelling"/></VbenField><VbenField label="Dispatch note" className="vben-delivery-span-2"><VbenTextarea value={dispatchNote} onChange={e=>setDispatchNote(e.target.value)} maxLength={2000}/></VbenField></div>}<VbenCard title="Immutable dispatch events" description="Assignment, reassignment, note and cancellation history recorded by the Backend."><VbenTable rows={dispatchDetail.events||[]} keyField="created_at" ariaLabel="Dispatch events" emptyTitle="No dispatch events" columns={[{key:'event_type',label:'Event',render:r=><VbenBadge tone="neutral">{humanize(r.event_type)}</VbenBadge>},{key:'actor_type',label:'Actor',render:r=>humanize(r.actor_type)},{key:'from_status',label:'From',render:r=>humanize(r.from_status)||'—'},{key:'to_status',label:'To',render:r=>humanize(r.to_status)||'—'},{key:'reason',label:'Reason',render:r=>r.reason||'—'},{key:'created_at',label:'Time',render:r=><VbenDateTime value={r.created_at}/>}]} /></VbenCard></div>}</VbenModal>

  <VbenToast message={toast} onDone={()=>setToast('')}/>
 </div>;
}

function MethodsTab({loading,methods,q,setQ,mode,setMode,statusFilter,setStatusFilter,has,onEdit,products,openDigitalConversion}){return <div className="delivery-tab-body">{has('catalog.read')&&<VbenCard title="Digital products use Product Nature, not Delivery Methods" description="DIGITAL_ACCESS and DIGITAL_DOWNLOAD are secure product-entitlement modes and do not belong in physical delivery pricing."><div className="vben-delivery-digital-guidance"><VbenAlert tone="info" title="Selling an image or video?">Use Product Nature for digital access. Digital-only carts skip the physical Delivery method section at checkout.</VbenAlert>{has('catalog.write')&&<VbenButton variant="secondary" icon="products" onClick={openDigitalConversion} disabled={!products.length}>Convert an existing product</VbenButton>}</div></VbenCard>}<div className="vben-delivery-toolbar"><VbenInput icon="search" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search name, code or mode"/><VbenSelect value={mode} onChange={e=>setMode(e.target.value)}><option value="">All modes</option><option>SHIPPING</option><option>LOCAL_DELIVERY</option><option>PICKUP</option></VbenSelect><VbenSelect value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">All statuses</option><option>ACTIVE</option><option>INACTIVE</option></VbenSelect><span className="vben-delivery-result-count">{methods.length} shown</span></div>{loading?<div className="vben-delivery-loading"><VbenSkeleton lines={5}/></div>:<VbenTable ariaLabel="Delivery methods" rows={methods} keyField="id" emptyTitle="No delivery methods" emptyDescription="Configure a shipping, local delivery or pickup method for checkout." columns={[{key:'name',label:'Method',render:r=><button className="vben-delivery-method-link" onClick={()=>has('delivery.manage')&&onEdit(r)} disabled={!has('delivery.manage')}><span className="vben-delivery-method-icon"><VbenIcon name={r.fulfillment_mode==='SHIPPING'?'truck':r.fulfillment_mode==='PICKUP'?'mapPin':'box'} size={16}/></span><span><strong>{r.name}</strong><small>{r.code}</small></span></button>},{key:'fulfillment_mode',label:'Mode',render:r=><VbenBadge tone="neutral">{r.fulfillment_mode}</VbenBadge>},{key:'pricing_mode',label:'Checkout pricing',render:r=><div className="delivery-pricing-cell"><VbenBadge tone={r.pricing_mode==='ZONE_AWARE'?'success':'neutral'}>{r.pricing_mode==='ZONE_AWARE'?'ZONE AWARE':'BASELINE'}</VbenBadge>{r.pricing_mode==='ZONE_AWARE'&&<small>{r.zone_no_match_policy==='BASELINE_FALLBACK'?'Fallback to baseline':'Unmatched unavailable'}</small>}</div>},{key:'status',label:'Status',render:r=><VbenBadge tone={vbenStatusTone(r.status)}>{r.status}</VbenBadge>},{key:'flat_fee',label:'Baseline fee',render:r=><VbenMoney value={r.flat_fee}/>},{key:'free_over',label:'Free over',render:r=>r.free_over==null?'—':<VbenMoney value={r.free_over}/>},{key:'min_order',label:'Minimum',render:r=><VbenMoney value={r.min_order}/>},{key:'estimated_min_minutes',label:'ETA',render:r=><span className="vben-delivery-eta">{r.estimated_min_minutes??'—'}–{r.estimated_max_minutes??'—'} min</span>}]} />}</div>}
function ZonesTab({loading,zones,rates,methods,zoneAwareCount,has,onEditZone,onNewRate,onEditRate}){return <div className="delivery-tab-body"><VbenAlert tone="info" title="Zone rates are opt-in checkout inputs">Creating or editing a zone rate never activates it automatically. A Shipping or Local delivery method must be explicitly set to Zone-aware pricing in its Checkout pricing policy. {zoneAwareCount} method{zoneAwareCount===1?' is':'s are'} currently zone-aware.</VbenAlert><div className="delivery-zone-grid"><VbenCard title="Delivery zones" description="Store-scoped country/region or radius rules used only by explicitly zone-aware methods.">{loading?<VbenSkeleton lines={4}/>:<VbenTable rows={zones} keyField="id" ariaLabel="Delivery zones" emptyTitle="No delivery zones" emptyDescription="Create a zone before attaching a rate." columns={[{key:'name',label:'Zone',render:z=><button className="delivery-ops-link" disabled={!has('delivery.manage')} onClick={()=>has('delivery.manage')&&onEditZone(z)}><strong>{z.name}</strong><small>{z.code}</small></button>},{key:'match_type',label:'Match',render:z=>z.match_type==='RADIUS'?`${z.radius_km} km radius`:`${(z.country_codes||[]).join(', ')}${z.region_names?.length?` · ${z.region_names.join(', ')}`:''}`},{key:'status',label:'Status',render:z=><VbenBadge tone={vbenStatusTone(z.status)}>{z.status}</VbenBadge>},{key:'rate',label:'Rate',render:z=>has('delivery.manage')?<VbenButton size="sm" variant="secondary" onClick={()=>onNewRate(z.id)} disabled={!methods.length}>Add rate</VbenButton>:'—'}]} />}</VbenCard><VbenCard title="Configured zone rates" description="Address-based fee and ETA inputs. They affect checkout only when their Delivery Method is explicitly Zone-aware.">{loading?<VbenSkeleton lines={4}/>:<VbenTable rows={rates} keyField="id" ariaLabel="Delivery zone rates" emptyTitle="No zone rates" emptyDescription="Attach a shipping or local-delivery method to a zone." columns={[{key:'zone_code',label:'Zone',render:r=><strong>{r.zone_code}</strong>},{key:'delivery_method_name',label:'Method',render:r=><button className="delivery-ops-link" disabled={!has('delivery.manage')} onClick={()=>has('delivery.manage')&&onEditRate(r)}><strong>{r.delivery_method_name}</strong><small>{r.delivery_method_code}</small></button>},{key:'flat_fee',label:'Fee',render:r=><VbenMoney value={r.flat_fee}/>},{key:'free_over',label:'Free over',render:r=>r.free_over==null?'—':<VbenMoney value={r.free_over}/>},{key:'status',label:'Status',render:r=><VbenBadge tone={vbenStatusTone(r.status)}>{r.status}</VbenBadge>}]} />}</VbenCard></div></div>}
function DriversTab({loading,drivers,has,onEdit}){return <div className="delivery-tab-body">{loading?<div className="vben-delivery-loading"><VbenSkeleton lines={5}/></div>:<VbenTable rows={drivers} keyField="id" ariaLabel="Delivery drivers" emptyTitle="No drivers" emptyDescription="Create store-scoped drivers before assigning dispatches." columns={[{key:'display_name',label:'Driver',render:d=><button className="delivery-ops-link" disabled={!has('delivery.manage')} onClick={()=>has('delivery.manage')&&onEdit(d)}><strong>{d.display_name}</strong><small>{d.phone_e164||d.merchant_user_email||'No phone linked'}</small></button>},{key:'status',label:'Status',render:d=><VbenBadge tone={vbenStatusTone(d.status)}>{d.status}</VbenBadge>},{key:'vehicle_type',label:'Vehicle',render:d=><span>{d.vehicle_type?humanize(d.vehicle_type):'—'}{d.vehicle_label?` · ${d.vehicle_label}`:''}</span>},{key:'merchant_user_id',label:'Staff linkage',render:d=>d.merchant_user_email||d.merchant_user_id||'Standalone driver'}]} />}</div>}
function DispatchTab({loading,dispatches,drivers,status,setStatus,driverFilter,setDriverFilter,busy,onOpen}){return <div className="delivery-tab-body"><VbenAlert tone="info" title="Dispatch and fulfillment are separate">Driver assignment is audited here. Fulfillment status changes remain in Orders until the Driver mobile lifecycle is released.</VbenAlert><div className="delivery-dispatch-toolbar"><VbenSelect value={status} onChange={e=>setStatus(e.target.value)}><option value="">All dispatch statuses</option>{DISPATCH_STATUSES.map(s=><option key={s}>{s}</option>)}</VbenSelect><VbenSelect value={driverFilter} onChange={e=>setDriverFilter(e.target.value)}><option value="">All drivers</option>{drivers.map(d=><option key={d.id} value={d.id}>{d.display_name}</option>)}</VbenSelect><span>{dispatches.length} shown</span></div>{loading?<div className="vben-delivery-loading"><VbenSkeleton lines={6}/></div>:<VbenTable rows={dispatches} keyField="id" ariaLabel="Delivery dispatches" emptyTitle="No dispatch assignments" emptyDescription="Assign a real shipping or delivery fulfillment to an active driver." columns={[{key:'order_number',label:'Order',render:d=><button className="delivery-ops-link" onClick={()=>onOpen(d)} disabled={busy===`dispatch:${d.id}`}><strong>{d.order_number}</strong><small>{humanize(d.fulfillment_type)}</small></button>},{key:'driver_name',label:'Driver',render:d=><span>{d.driver_name}{d.vehicle_label?` · ${d.vehicle_label}`:''}</span>},{key:'status',label:'Dispatch',render:d=><VbenBadge tone={vbenStatusTone(d.status)}>{humanize(d.status)}</VbenBadge>},{key:'fulfillment_status',label:'Fulfillment',render:d=><VbenBadge tone={vbenStatusTone(d.fulfillment_status)}>{humanize(d.fulfillment_status)}</VbenBadge>},{key:'assigned_at',label:'Assigned',render:d=><VbenDateTime value={d.assigned_at}/>}]} />}</div>}

function PricingPolicyEditor({method,form,setForm,onSave,busy,error,activeRateCount}){
 const eligible=['SHIPPING','LOCAL_DELIVERY'].includes(method.fulfillment_mode);
 if(!eligible)return <VbenCard className="delivery-pricing-policy" title="Checkout pricing policy" description="Pricing mode is intentionally separate from the method fee editor."><VbenAlert tone="info" title="Pickup always uses Baseline pricing">Pickup has no delivery-address zone match, so zone-aware pricing is not available for this fulfillment mode.</VbenAlert><div className="delivery-pricing-policy-state"><span>Current policy</span><VbenBadge tone="neutral">BASELINE</VbenBadge></div></VbenCard>;
 return <VbenCard className="delivery-pricing-policy" title="Checkout pricing policy" description="Explicitly choose whether checkout uses this method’s baseline fee or an address-matched zone rate." data-testid="delivery-pricing-policy">
  {error&&<VbenAlert tone="danger" title={error.code||'Pricing policy rejected'}>{pricingErrorText(error)}</VbenAlert>}
  <div className="delivery-pricing-policy-grid">
   <VbenField label="Pricing mode"><VbenSelect value={form.pricing_mode} onChange={e=>setForm({...form,pricing_mode:e.target.value,zone_no_match_policy:e.target.value==='BASELINE'?'UNAVAILABLE':form.zone_no_match_policy})}><option value="BASELINE">Baseline — method fee / thresholds</option><option value="ZONE_AWARE">Zone-aware — match customer address</option></VbenSelect></VbenField>
   <VbenField label="If no active zone matches" hint="Used only by Zone-aware pricing."><VbenSelect value={form.zone_no_match_policy} disabled={form.pricing_mode!=='ZONE_AWARE'} onChange={e=>setForm({...form,zone_no_match_policy:e.target.value})}><option value="UNAVAILABLE">Unavailable — reject this delivery method</option><option value="BASELINE_FALLBACK">Baseline fallback — use method baseline fee</option></VbenSelect></VbenField>
  </div>
  <div className="delivery-pricing-policy-status"><div><span>Active zone rates detected</span><strong>{activeRateCount}</strong></div><div><span>Current Backend policy</span><strong>{humanize(method.pricing_mode||'BASELINE')}</strong></div></div>
  {form.pricing_mode==='ZONE_AWARE'&&activeRateCount===0&&<VbenAlert tone="warning" title="Active rate required">Add at least one ACTIVE rate inside an ACTIVE zone for this method. The Backend will reject activation until that requirement is satisfied.</VbenAlert>}
  <div className="delivery-pricing-policy-notes"><p><strong>Baseline</strong> uses this method’s flat fee, free-over threshold, minimum order and ETA.</p><p><strong>Zone-aware</strong> resolves the submitted customer address on the Backend, freezes the matched zone/rate into the fulfillment, then applies VIP delivery benefits downstream.</p></div>
  <div className="delivery-pricing-policy-actions"><span>Saving a zone or rate never changes this policy automatically.</span><VbenButton variant={form.pricing_mode==='ZONE_AWARE'?'primary':'secondary'} onClick={onSave} loading={busy}>Apply pricing policy</VbenButton></div>
 </VbenCard>;
}
function MethodForm({form,setForm,onSubmit,id,includeCode}){return <form id={id} onSubmit={onSubmit} className="vben-delivery-form"><div className="vben-delivery-form-grid">{includeCode&&<><VbenField label="Code" required><VbenInput value={form.code} onChange={e=>setForm({...form,code:e.target.value})} required/></VbenField><VbenField label="Name" required><VbenInput value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></VbenField><VbenField label="Fulfillment mode"><VbenSelect value={form.fulfillment_mode} onChange={e=>setForm({...form,fulfillment_mode:e.target.value})}><option>SHIPPING</option><option>LOCAL_DELIVERY</option><option>PICKUP</option></VbenSelect></VbenField></>}<MethodFields form={form} setForm={setForm} includeName={!includeCode}/></div></form>}
function MethodFields({form,setForm,includeName=true}){return <>{includeName&&<VbenField label="Name"><VbenInput value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></VbenField>}<VbenField label="Status"><VbenSelect value={form.status||'ACTIVE'} onChange={e=>setForm({...form,status:e.target.value})}><option>ACTIVE</option><option>INACTIVE</option></VbenSelect></VbenField><VbenField label="Flat fee"><VbenInput type="number" min="0" step="0.01" value={form.flat_fee??0} onChange={e=>setForm({...form,flat_fee:e.target.value})}/></VbenField><VbenField label="Free over"><VbenInput type="number" min="0" step="0.01" value={form.free_over??''} onChange={e=>setForm({...form,free_over:e.target.value})} placeholder="Optional"/></VbenField><VbenField label="Minimum order"><VbenInput type="number" min="0" step="0.01" value={form.min_order??0} onChange={e=>setForm({...form,min_order:e.target.value})}/></VbenField><VbenField label="Min ETA (minutes)"><VbenInput type="number" min="0" value={form.estimated_min_minutes??''} onChange={e=>setForm({...form,estimated_min_minutes:e.target.value})}/></VbenField><VbenField label="Max ETA (minutes)"><VbenInput type="number" min="0" value={form.estimated_max_minutes??''} onChange={e=>setForm({...form,estimated_max_minutes:e.target.value})}/></VbenField><VbenField label="Sort order"><VbenInput type="number" value={form.sort_order??0} onChange={e=>setForm({...form,sort_order:e.target.value})}/></VbenField><VbenField label="Public configuration (JSON)" hint="Customer-safe options only; never put secrets here." className="vben-delivery-span-2"><VbenTextarea className="vben-delivery-code" value={form.public_config||'{}'} onChange={e=>setForm({...form,public_config:e.target.value})}/></VbenField></>}
function ZoneForm({form,setForm,onSubmit,id,includeCode}){return <form id={id} onSubmit={onSubmit} className="vben-delivery-form"><div className="vben-delivery-form-grid">{includeCode&&<VbenField label="Code" required><VbenInput value={form.code} onChange={e=>setForm({...form,code:e.target.value})} placeholder="PHNOM_PENH" required/></VbenField>}<ZoneFields form={form} setForm={setForm}/></div></form>}
function ZoneFields({form,setForm}){return <><VbenField label="Name" required><VbenInput value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})} required/></VbenField><VbenField label="Status"><VbenSelect value={form.status||'ACTIVE'} onChange={e=>setForm({...form,status:e.target.value})}><option>ACTIVE</option><option>INACTIVE</option></VbenSelect></VbenField><VbenField label="Match type"><VbenSelect value={form.match_type||'COUNTRY_REGION'} onChange={e=>setForm({...form,match_type:e.target.value})}><option value="COUNTRY_REGION">Country / region</option><option value="RADIUS">Radius</option></VbenSelect></VbenField>{form.match_type==='COUNTRY_REGION'?<><VbenField label="Country codes" hint="Comma-separated ISO alpha-2 codes, e.g. KH, TH"><VbenInput value={form.country_codes||''} onChange={e=>setForm({...form,country_codes:e.target.value})} required/></VbenField><VbenField label="Region names" hint="Optional comma-separated state/city/region labels"><VbenInput value={form.region_names||''} onChange={e=>setForm({...form,region_names:e.target.value})}/></VbenField></>:<><VbenField label="Center latitude"><VbenInput type="number" min="-90" max="90" step="0.000001" value={form.center_latitude??''} onChange={e=>setForm({...form,center_latitude:e.target.value})} required/></VbenField><VbenField label="Center longitude"><VbenInput type="number" min="-180" max="180" step="0.000001" value={form.center_longitude??''} onChange={e=>setForm({...form,center_longitude:e.target.value})} required/></VbenField><VbenField label="Radius (km)"><VbenInput type="number" min="0.001" step="0.1" value={form.radius_km??''} onChange={e=>setForm({...form,radius_km:e.target.value})} required/></VbenField></>}<VbenField label="Sort order"><VbenInput type="number" value={form.sort_order??0} onChange={e=>setForm({...form,sort_order:e.target.value})}/></VbenField></>}
function RateForm({form,setForm,zones,methods,onSubmit,id}){return <form id={id} onSubmit={onSubmit} className="delivery-ops-form-stack"><VbenAlert tone="info" title="Zone rate does not auto-activate pricing">This stores an address-based fee/ETA input. Checkout uses it only after the related Delivery Method is explicitly set to Zone-aware pricing.</VbenAlert><div className="vben-delivery-form-grid"><VbenField label="Zone"><VbenSelect value={form.zone_id} onChange={e=>setForm({...form,zone_id:e.target.value})}><option value="">Choose zone</option>{zones.map(z=><option key={z.id} value={z.id}>{z.name} · {z.code}</option>)}</VbenSelect></VbenField><VbenField label="Delivery method"><VbenSelect value={form.delivery_method_id} onChange={e=>setForm({...form,delivery_method_id:e.target.value})}><option value="">Choose shipping / local delivery</option>{methods.map(m=><option key={m.id} value={m.id}>{m.name} · {m.fulfillment_mode}</option>)}</VbenSelect></VbenField><RateFields form={form} setForm={setForm}/></div></form>}
function RateFields({form,setForm}){return <><VbenField label="Status"><VbenSelect value={form.status||'ACTIVE'} onChange={e=>setForm({...form,status:e.target.value})}><option>ACTIVE</option><option>INACTIVE</option></VbenSelect></VbenField><VbenField label="Flat fee"><VbenInput type="number" min="0" step="0.01" value={form.flat_fee??0} onChange={e=>setForm({...form,flat_fee:e.target.value})}/></VbenField><VbenField label="Free over"><VbenInput type="number" min="0" step="0.01" value={form.free_over??''} onChange={e=>setForm({...form,free_over:e.target.value})} placeholder="Optional"/></VbenField><VbenField label="Minimum order"><VbenInput type="number" min="0" step="0.01" value={form.min_order??0} onChange={e=>setForm({...form,min_order:e.target.value})}/></VbenField><VbenField label="Min ETA (minutes)"><VbenInput type="number" min="0" value={form.estimated_min_minutes??''} onChange={e=>setForm({...form,estimated_min_minutes:e.target.value})}/></VbenField><VbenField label="Max ETA (minutes)"><VbenInput type="number" min="0" value={form.estimated_max_minutes??''} onChange={e=>setForm({...form,estimated_max_minutes:e.target.value})}/></VbenField><VbenField label="Priority"><VbenInput type="number" value={form.priority??0} onChange={e=>setForm({...form,priority:e.target.value})}/></VbenField></>}
function DriverForm({form,setForm,onSubmit,id}){return <form id={id} onSubmit={onSubmit} className="vben-delivery-form"><div className="vben-delivery-form-grid"><DriverFields form={form} setForm={setForm}/></div></form>}
function DriverFields({form,setForm}){return <><VbenField label="Display name" required><VbenInput value={form.display_name||''} onChange={e=>setForm({...form,display_name:e.target.value})} required/></VbenField><VbenField label="Phone"><VbenInput value={form.phone_e164||''} onChange={e=>setForm({...form,phone_e164:e.target.value})} placeholder="+855…"/></VbenField><VbenField label="Status"><VbenSelect value={form.status||'ACTIVE'} onChange={e=>setForm({...form,status:e.target.value})}><option>ACTIVE</option><option>INACTIVE</option><option>SUSPENDED</option></VbenSelect></VbenField><VbenField label="Vehicle type"><VbenSelect value={form.vehicle_type||''} onChange={e=>setForm({...form,vehicle_type:e.target.value})}><option value="">Not specified</option><option>BIKE</option><option>MOTORBIKE</option><option>CAR</option><option>VAN</option><option>TRUCK</option><option>OTHER</option></VbenSelect></VbenField><VbenField label="Vehicle label"><VbenInput value={form.vehicle_label||''} onChange={e=>setForm({...form,vehicle_label:e.target.value})} placeholder="Plate / vehicle name"/></VbenField><VbenField label="Merchant user ID" hint="Optional existing merchant-user public ID. Driver auth is not enabled in this release."><VbenInput value={form.merchant_user_id||''} onChange={e=>setForm({...form,merchant_user_id:e.target.value})} placeholder="Optional"/></VbenField></>}
